package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real original 081 writer, witnesses, grants and immutable journals. The unavailable 083/084 assembler is an explicit private-proof fixture; this is NOT a professional execution success claim. */
class FormalScoreBindingWorkflowTest {
 ExpertFixture f;ExpertEvaluationFixture e;JsonNode qualification;FormalAgentPublicationSchema json;FormalEvaluationScoreBindingService service;FormalAgentAcceptanceEvidence evidence;JsonNode outer;
 @BeforeEach void setup()throws Exception{f=new ExpertFixture();qualification=f.author();f.approve(qualification);f.now=f.now.plusMinutes(1);e=new ExpertEvaluationFixture(f);e.append();e.finish();json=new FormalAgentPublicationSchema(f.f.json);evidence=mock(FormalAgentAcceptanceEvidence.class);service=new FormalEvaluationScoreBindingService(f.f.access,evidence,new FormalEvaluationScoreBindingSchema(json),json,f.service,f.store,f.authority);var n=f.f.json.object().put("schema_version","1.0.0");n.set("evaluation",f.f.json.tree(new PermissionProtocol.Basis(e.definition.evaluation_id(),e.hash)));n.set("statistics_policy",f.f.json.tree(new PermissionProtocol.Basis(FormalInputFixture.id(900),"a".repeat(64))));n.set("binding",e.bindRequest(qualification));outer=n;
 when(evidence.prepareScoreBinding(any(),anyString(),any())).thenReturn(mock(FormalAgentAcceptanceEvidence.Prepared.class));when(evidence.prepareScoreBindingRead(any(),anyString(),any())).thenReturn(mock(FormalAgentAcceptanceEvidence.Prepared.class));
 when(evidence.requireScoreBinding(any(),any(),any())).thenAnswer(i->{var a=(EnterpriseAccess.Admission)i.getArgument(0);JsonNode request=i.getArgument(1);var snapshot=e.service.requireAcceptance(a,e.definition.evaluation_id());var permit=mock(FormalAgentAcceptanceEvidence.ScoreBindingPermit.class);when(permit.requireConsumer(eq(a),any())).thenAnswer(x->{snapshot.requireConsumer(a,e.definition.evaluation_id());return snapshot;});var w=f.f.json.object().put("schema_version","1.0.0").put("request_body_sha256",json.hash(request)).put("definition_sha256",e.hash);w.set("request",request.deepCopy());w.set("statistics_policy",request.required("statistics_policy").deepCopy());w.putObject("policy_authorizations").put("explicit_test_boundary",true);w.putObject("execution_authorizations").put("explicit_test_boundary",true);when(permit.witness()).thenReturn(w);when(permit.classification()).thenReturn("INTERNAL");return permit;});
 when(evidence.requireScoreBindingRead(any(),any(),any())).thenAnswer(i->{var a=(EnterpriseAccess.Admission)i.getArgument(0);var snapshot=e.service.requireAcceptance(a,e.definition.evaluation_id());var read=mock(FormalAgentAcceptanceEvidence.ScoreBindingRead.class);when(read.requireConsumer(eq(a),any())).thenAnswer(x->{snapshot.requireConsumer(a,e.definition.evaluation_id());return snapshot;});return read;});}
 @AfterEach void close()throws Exception{f.close();}
 JsonNode bind(String key,JsonNode body)throws Exception{return service.bind(f.f.subject,"1",key,json.canonical(body).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test void exactOuterRequestAndOriginal081ReceiptAreAnchoredAtomically()throws Exception{var r=bind("formal-score-key-001",outer);assertEquals(json.hash(outer),r.path("request_body_sha256").asText());assertEquals(1,f.bindings.size());var journal=f.journals.values().stream().filter(x->x.kind().equals("SCORE_BIND")).findFirst().orElseThrow();assertEquals(r.path("receipt"),f.schema.parse(journal.receiptJson().getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertEquals(outer,f.schema.parse(journal.authorizationsJson().getBytes(java.nio.charset.StandardCharsets.UTF_8)).path("formal_preparation").path("request"));assertEquals(r,service.recover(f.f.subject,"1","formal-score-key-001",outer));}
 @Test void sameKeySameInnerButChangedPolicyIsConflict()throws Exception{bind("formal-score-key-002",outer);var changed=(ObjectNode)outer.deepCopy();changed.withObject("/statistics_policy").put("version_id",FormalInputFixture.id(901));var ex=ExpertQualificationServiceTest.cause(assertThrows(Exception.class,()->bind("formal-score-key-002",changed)));assertEquals(ErrorCode.IDEMPOTENCY_CONFLICT,((TenantAccessException)ex).code());assertEquals(1,f.bindings.size());}
 @Test void old081RecordWithoutFormalWitnessCannotBecomeNewReceipt()throws Exception{f.service.bindScore(f.f.subject,"1","formal-score-key-003",outer.required("binding"));assertThrows(Exception.class,()->service.recover(f.f.subject,"1","formal-score-key-003",outer));verify(evidence,never()).prepareScoreBindingRead(any(),anyString(),any());}
 @Test void recoveredReadDoesNotNeedCurrentScoreWriteGrant()throws Exception{var r=bind("formal-score-key-004",outer);f.f.grants.removeIf(g->g.action().equals("evaluation.score"));assertEquals(r,service.recover(f.f.subject,"1","formal-score-key-004",outer));assertEquals(1,f.bindings.size());}
 @Test void alteredOriginalAuditBlocksRecovery()throws Exception{bind("formal-score-key-005",outer);f.audits.clear();assertThrows(Exception.class,()->service.recover(f.f.subject,"1","formal-score-key-005",outer));}
 @Test void anotherActorCannotRecoverOriginalKey()throws Exception{bind("formal-score-key-006",outer);f.actor(FormalInputFixture.id(4));assertThrows(Exception.class,()->service.recover(f.f.subject,"1","formal-score-key-006",outer));}
 @Test void realQualificationRevocationCannotBeBypassedByPreparationWitness()throws Exception{bind("formal-score-key-007",outer);f.actor(FormalInputFixture.id(4));f.service.decide(f.f.subject,"1","revoke-qualified-expert",f.decision(qualification,"REVOKE","2"));f.actor(f.expert);assertThrows(Exception.class,()->service.recover(f.f.subject,"1","formal-score-key-007",outer));}
}
